 @media(max-width:1260px){main,footer{margin-inline:30px}}@media(max-width:720px){main,footer{margin-inline:18px}.tabs{gap:24px}.toolbar{flex-wrap:wrap}.toolbar label{flex:1}.toolbar .actions{width:100%}.puzzle-list{grid-template-columns:1fr}.puzzle-card{padding:10px 12px}}
 @media print{ :global(body){background:white;color:black}.app-shell{display:none!important}.print-area{display:block;font-family:Arial,sans-serif}.print-area.landscape{page:wsc-landscape}.pack-cover{min-height:245mm;display:flex;flex-direction:column;justify-content:center;break-after:page}.print-area.landscape .pack-cover{min-height:170mm}.print-area h1{font-size:28px;letter-spacing:0}.print-area h2{font-size:18px}.round-preview{min-height:245mm;padding:20mm 12mm;break-before:page;break-after:page}.landscape .round-preview{min-height:170mm;padding:12mm 16mm}.round-preview h2{font-size:32px;margin:8mm 0 3mm}.round-preview .round-meta{font-size:15px}.round-preview h3{margin-top:16mm}.round-preview ol{padding:0;list-style:none;border-top:2px solid #222;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:12mm}.round-preview li{display:flex;justify-content:space-between;gap:5mm;padding:3mm 0;border-bottom:1px solid #bbb;font-size:12px;break-inside:avoid}.print-puzzle-grid{display:grid;grid-template-columns:1fr;gap:0}.print-puzzle{min-height:245mm;padding:4mm 0;break-before:page;break-inside:avoid;overflow:hidden;display:flex;flex-direction:column}.print-puzzle:first-child{break-before:auto}.print-puzzle-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:8mm}.print-puzzle-heading h2{margin:2mm 0}.time-box{flex:0 0 30mm;height:16mm;border:1.5px solid #222;padding:2mm;font-size:8px;font-weight:700;text-align:center;letter-spacing:1px}.time-box span{display:block;font-size:14px;letter-spacing:10px;margin-left:10px}.print-puzzle img{display:block;width:170mm;height:190mm;margin:auto auto 3mm;object-fit:contain}.print-puzzle p{font-size:10pt;line-height:1.35}.landscape .print-puzzle-grid{grid-template-columns:1fr 1fr;gap:10mm;break-before:page}.landscape .print-puzzle{min-height:170mm;break-before:auto;border-right:1px solid #bbb;padding-right:5mm}.landscape .print-puzzle:nth-child(even){border-right:0;padding-right:0}.landscape .print-puzzle:nth-child(2n+3){break-before:page}.landscape .print-puzzle img{width:122mm;height:112mm}.print-puzzle-grid.round-two{display:block}.print-puzzle.samurai{page:wsc-portrait;min-height:245mm;border:0!important;padding:4mm 0!important}.print-puzzle.samurai img{width:185mm;height:210mm}.print-puzzle-grid.round-eleven .print-puzzle img{object-fit:contain}.print-credit{display:none}@page{size:A4 portrait;margin:15mm}@page wsc-landscape{size:A4 landscape;margin:12mm}@page wsc-portrait{size:A4 portrait;margin:10mm}}
 @media print{
